export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"tr","term":"Tüm zamanların en yüksek seviyesi (ATH)","aka":["ATH","all-time high","zirve","rekor seviye"],"short":"Tüm zamanların en yüksek seviyesi (all-time high, ATH), bir kripto paranın işlem görmeye başladığından bu yana ulaştığı en yüksek fiyattır.","body":["Veri siteleri her coin için ATH değerini ve bu seviyenin hangi tarihte görüldüğünü gösterir. Güncel fiyatın ATH'den ne kadar uzakta olduğu yüzde olarak verilir. Tersi durumda, en düşük seviyeye ATL (all-time low) denir.",["Fiyat ATH'ye yaklaştığında piyasada heyecan ve ",["FOMO","fomo"]," artar. ATH kırıldığında, üstünde daha önce işlem yapılmış bir seviye olmadığı için teknik analizde direnç noktası bulunmaz; buna fiyat keşfi denir. Bu dönemler hem sert yükselişlere hem de ani geri çekilmelere sahne olabilir."],"ATH'yi borsadan borsaya küçük farklarla görebilirsiniz, çünkü her borsanın kendi fiyatı vardır. Ayrıca bir coinin dolar cinsinden ATH'si ile lira veya başka bir para birimi cinsinden ATH'si farklı tarihlerde olabilir."],"example":["Bir coinin ATH'si 120 ",["USDT","usdt"],", güncel fiyatı 48 USDT olsun. Coin, ATH'sinin yüzde 60 altında işlem görüyor: (120 - 48) / 120 = 0,60. ATH'ye geri dönmesi için fiyatın 48'den 120'ye, yani yüzde 150 yükselmesi gerekir. Bu asimetri önemlidir: yüzde 60 düşüşü telafi etmek için yüzde 60 değil, yüzde 150 yükseliş gerekir. Lira bazında bakarsanız, kur değiştiği için aynı coin dolar ATH'sinin altındayken lira cinsinden yeni bir zirve görebilir."],"mistakes":["ATH'den çok düşmüş bir coini otomatik olarak ucuz ve geri dönecek sanmak.","ATH kırılırken plansız ve kaldıraçlı alım yapmak.","Farklı borsalardaki ve para birimlerindeki ATH değerlerini karıştırmak."],"faq":[{"q":"ATH ne demek?","a":"All-time high ifadesinin kısaltmasıdır ve bir varlığın tarihindeki en yüksek fiyatı anlatır. Kripto piyasasında yeni bir ATH genellikle büyük ilgi çeker."},{"q":"ATH'den sonra fiyat düşer mi?","a":"Her zaman değil. Bazı varlıklar ATH'yi kırdıktan sonra yükselmeye devam eder, bazıları ise sert geri çekilir; sonucu önceden bilmek mümkün değildir."}],"title":"ATH nedir? Tüm zamanların en yüksek seviyesi","description":"ATH'nin ne demek olduğunu, ATH'den uzaklığın nasıl hesaplandığını ve yüzde düşüşlerin neden telafisinin zor olduğunu öğrenin.","related":[["bull-market","Boğa piyasası (bull market)","Boğa piyasası (bull market), fiyatların uzun bir dönem boyunca genel olarak yükseldiği, yatırımcı iyimserliğinin ve işlem hacminin arttığı piyasa evresidir."],["fomo","FOMO (fırsatı kaçırma korkusu)","FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["support-and-resistance","Destek ve direnç (Support and resistance)","Destek ve direnç, grafikte fiyatın daha önce düşüşünün (destek) veya yükselişinin (direnç) durduğu ve alıcılarla satıcıların yoğunlaştığı fiyat bölgeleridir."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"tr","term":"Coin teminatlı vadeli kontrat (Coin-margined futures)","aka":["coin-margined","ters vadeli kontrat","inverse futures","COIN-M"],"short":"Coin teminatlı vadeli kontrat, teminatın ve kâr-zararın USDT yerine BTC veya ETH gibi dayanak coinin kendisiyle hesaplandığı ters (inverse) vadeli işlem sözleşmesidir.","body":[["Bu kontratlarda ",["pozisyon büyüklüğü","position-sizing"]," genellikle dolar cinsinden sabit değerli sözleşmelerle ifade edilir; örneğin bazı borsalarda bir ",["BTC","bitcoin"]," kontratı 100 dolardır. Teminatınızı BTC olarak yatırırsınız ve kazancınız ya da kaybınız da BTC olarak hesaplanır."],["Bu yapı kâr-zarar hesabını doğrusal olmaktan çıkarır. Long pozisyonda fiyat yükselirken hem pozisyon kazanır hem de teminat olarak tuttuğunuz coinin değeri artar; fiyat düşerken ise iki kayıp üst üste biner. Bu yüzden coin teminatlı long, ",["USDT","usdt"]," teminatlıya göre düşüşlerde daha hızlı erir."],"Coin teminatlı kontratlar özellikle elinde zaten BTC tutan madenciler ve uzun vadeli yatırımcılar için kullanışlıdır; coini satmadan dolar değerini korumak amacıyla short açabilirler. Kontrat büyüklüğü ve hesaplama ayrıntıları borsaya göre değişir, kontrat şartname sayfasını kontrol edin."],"example":"Elinizde 1 BTC var ve BTC 60.000 USDT. Dolar değerini korumak için coin teminatlı kontratta 60.000 dolarlık short açıyorsunuz. BTC 50.000'e düşerse 1 BTC'niz 50.000 dolar eder, ama short pozisyonunuz 60.000 × (1/50.000 − 1/60.000) = 0,2 BTC kazandırır. Toplam 1,2 BTC × 50.000 = 60.000 dolar eder; başlangıçtaki dolar değeriniz ücretler ve fonlama hariç korunmuş olur.","mistakes":["Coin teminatlı long pozisyonun, fiyat düşüşünde teminat değeri de düştüğü için çifte kayıp yarattığını hesaba katmamak.","Kâr-zararın USDT değil coin cinsinden yazıldığını gözden kaçırıp yanlış yorumlamak.","Kontrat başına dolar değerini kontrol etmeden pozisyon büyüklüğü girmek."],"faq":[{"q":"Coin teminatlı ve USDT teminatlı kontrat farkı nedir?","a":"USDT teminatlıda teminat ve kâr-zarar USDT ile, coin teminatlıda ise dayanak coinle hesaplanır. Coin teminatlıda kâr-zarar doğrusal değildir ve teminatın değeri de fiyatla birlikte değişir."},{"q":"Neden ters (inverse) kontrat deniyor?","a":"Kâr-zarar, fiyatın tersi (1/fiyat) üzerinden hesaplandığı için bu ad verilir. Fiyat dolar cinsinden verilir ama ödemeler coinle yapılır."}],"title":"Coin teminatlı (inverse) vadeli kontrat nedir?","description":"Coin teminatlı vadeli kontratın nasıl çalıştığını, doğrusal olmayan kâr-zararı ve hedge kullanımını öğrenin.","related":[["usdt-margined-futures","USDT teminatlı vadeli kontrat (USDT-margined futures)","USDT teminatlı vadeli kontrat, teminatın USDT olarak yatırıldığı ve kâr-zararın doğrudan USDT cinsinden, fiyat hareketiyle doğrusal olarak hesaplandığı vadeli işlem sözleşmesidir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["unrealized-pnl","Gerçekleşmemiş kâr/zarar (Unrealized PnL)","Gerçekleşmemiş kâr/zarar (unrealized PnL), açık bir pozisyonun mevcut fiyata göre hesaplanan ama pozisyon kapatılmadığı için henüz kesinleşmemiş kâr veya zararıdır."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"tr","term":"Hedge (Riskten korunma)","aka":["hedge","hedging","riskten korunma","korunma pozisyonu"],"short":"Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir.","body":[["Kriptoda en yaygın hedge, elinizdeki spot coinleri satmadan vadeli kontratta short açmaktır. Fiyat düşerse spot varlığınız değer kaybeder ama ",["short pozisyon","long-and-short"]," kazanır; iki etki birbirini büyük ölçüde dengeler. Bu sayede vergi, uzun vadeli hedef veya ",["staking","staking"]," gibi nedenlerle tutmak istediğiniz coinleri satmadan değer dalgalanmasına karşı korunursunuz."],["Hedge ücretsiz değildir. İşlem ücretleri, ",["perpetual","perpetual-futures"]," kontratlarda fonlama ödemeleri ve opsiyonlarda prim gibi maliyetler vardır. Ayrıca hedge kayıpları sınırladığı gibi kazançları da sınırlar: fiyat yükselirse spot kazancınız short zararıyla dengelenir."],["Kısmi hedge de mümkündür; örneğin varlığınızın yalnızca yarısını korumak. Opsiyonlarla yapılan hedge, örneğin satım (put) opsiyonu almak, yükseliş potansiyelini korurken düşüşü sınırlar ama prim maliyeti getirir. Hedge bacağının ",["likidasyon","liquidation"]," riskini de takip etmeniz gerekir."]],"example":["Elinizde 10 ",["ETH","ethereum"]," var ve ETH 2.500 ",["USDT","usdt"],"; toplam değer 25.000 USDT. Önümüzdeki iki hafta için düşüşten korunmak amacıyla 3x kaldıraçla 10 ETH'lik short açıyorsunuz, bunun için yaklaşık 8.333 USDT teminat bağlıyorsunuz. ETH 2.200'e düşerse spot varlığınız 3.000 USDT kaybeder, short pozisyon 3.000 USDT kazanır. Fonlama ve ücretler toplam 40 USDT tuttuysa, iki haftanın net maliyeti yalnızca bu 40 USDT olur."],"mistakes":["Hedge pozisyonunu yüksek kaldıraçla açıp fiyat yükselince short bacağın tasfiye edilmesine izin vermek.","Fonlama ödemelerinin uzun süreli hedgede birikerek ciddi maliyet yarattığını hesaba katmamak.","Hedge pozisyonunun yükselişteki kazancı da sınırladığını unutmak."],"faq":[{"q":"Kripto portföyü nasıl hedge edilir?","a":"En yaygın yol, tuttuğunuz coin için vadeli kontratta aynı büyüklükte short açmaktır. Alternatif olarak satım (put) opsiyonu alarak düşüşe karşı korunabilirsiniz."},{"q":"Hedge ile tamamen risksiz olur muyum?","a":"Hayır. Ücret, fonlama, likidasyon ve karşı taraf riski devam eder. Hedge fiyat riskini azaltır, ama diğer riskleri ortadan kaldırmaz."}],"title":"Hedge nedir? Kriptoda riskten korunma nasıl yapılır","description":"Kriptoda hedge stratejisinin nasıl çalıştığını, vadeli ve opsiyonla korunmayı ve maliyetlerini örnekle öğrenin.","related":[["short-selling","Açığa satış (Short selling)","Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["options","Kripto opsiyon (Crypto options)","Kripto opsiyon, sahibine belirli bir kripto varlığı belirli bir fiyattan belirli bir tarihte veya o tarihe kadar alma (call) ya da satma (put) hakkı veren, ama yükümlülük getirmeyen türev sözleşmedir."],["portfolio-margin","Portföy marjini (Portfolio margin)","Portföy marjini, teminat gereksinimini her pozisyon için ayrı ayrı değil, tüm portföyün toplam riskine göre hesaplayan gelişmiş bir marjin modudur."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"tr","term":"Kripto opsiyon (Crypto options)","aka":["opsiyon","options","alım opsiyonu","satım opsiyonu"],"short":"Kripto opsiyon, sahibine belirli bir kripto varlığı belirli bir fiyattan belirli bir tarihte veya o tarihe kadar alma (call) ya da satma (put) hakkı veren, ama yükümlülük getirmeyen türev sözleşmedir.","body":["Alım opsiyonu (call), fiyatın kullanım fiyatının (strike) üzerine çıkmasından kazanç sağlar; satım opsiyonu (put) ise fiyatın kullanım fiyatının altına düşmesinden kazanç sağlar. Opsiyonu alan taraf bu hak için prim öder. Opsiyonu alan için olası en büyük kayıp ödenen primdir.","Opsiyonu satan (yazan) taraf primi alır, ama fiyat aleyhine giderse ciddi kayıplara maruz kalabilir ve teminat yatırması gerekir. Opsiyon fiyatı, dayanak fiyatın yanında vadeye kalan süreye ve beklenen volatiliteye bağlıdır; vade yaklaştıkça zaman değeri erir.",["Kripto opsiyonları Deribit, OKX ve Binance gibi borsalarda işlem görür. Çoğu Avrupa tipidir, yani yalnızca vade günü kullanılabilir, ve nakit uzlaşmalıdır. Opsiyonlar ",["hedge","hedging"]," için, örneğin portföyü put ile korumak için, veya belirli bir fiyat aralığı beklentisini işlemek için kullanılır. Bazı borsaların ",["çift yatırım","dual-investment"]," gibi getiri ürünleri de arka planda opsiyon satışına dayanır."]],"example":[["BTC","bitcoin"]," 60.000 ",["USDT","usdt"]," iken 30 gün vadeli, 65.000 kullanım fiyatlı 1 BTC'lik bir call opsiyonu için 1.500 USDT prim ödüyorsunuz. Vade günü BTC 70.000 olursa opsiyonun değeri 5.000 USDT'dir ve net kazancınız 3.500 USDT olur. Başa baş noktanız 66.500 USDT'dir. Vade günü BTC 65.000'in altındaysa opsiyon değersiz sona erer ve kaybınız ödediğiniz 1.500 USDT ile sınırlı kalır."],"mistakes":["Fiyat doğru yöne gitse bile zaman değerinin erimesi yüzünden opsiyonun değer kaybedebileceğini bilmemek.","Opsiyon satmanın sabit ve güvenli bir gelir olduğunu sanmak; sert hareketlerde kayıp primden çok büyük olabilir.","Başa baş noktasını hesaplamadan yalnızca kullanım fiyatına bakmak."],"faq":[{"q":"Call ve put opsiyon farkı nedir?","a":"Call, belirli bir fiyattan alma hakkıdır ve fiyat yükselince değer kazanır. Put, belirli bir fiyattan satma hakkıdır ve fiyat düşünce değer kazanır."},{"q":"Opsiyon alırken en fazla ne kadar kaybederim?","a":"Opsiyon alıcısı olarak en fazla ödediğiniz primi kaybedersiniz. Opsiyon satıcısının ise kaybı çok daha büyük olabilir."},{"q":"Opsiyon ile vadeli kontrat farkı nedir?","a":"Vadeli kontrat her iki tarafa da yükümlülük getirir ve kâr-zarar doğrusaldır. Opsiyon alıcıya yalnızca hak verir, bu yüzden kayıp primle sınırlıdır."}],"title":"Kripto opsiyon nedir? Call ve put nasıl çalışır","description":"Kripto opsiyonlarda call ve put farkını, prim, kullanım fiyatı ve başa baş hesabını örnekle öğrenin.","related":[["futures-contract","Vadeli işlem sözleşmesi (Futures contract)","Vadeli işlem sözleşmesi, bir varlığı sahiplenmeden fiyatı üzerine işlem yapmanızı sağlayan ve iki tarafın varlığı belirli bir fiyattan ileride alıp satmayı kabul ettiği türev sözleşmedir."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["dual-investment","Çift yatırım (dual investment)","Çift yatırım (dual investment), belirlenen vade sonunda fiyatın hedef fiyata göre konumuna bağlı olarak paranızı ya ana coin ya da stablecoin olarak, her iki durumda da ek getiriyle geri aldığınız opsiyon tabanlı bir üründür."]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"tr","term":"Emanetçi cüzdan (Custodial wallet)","aka":["saklamalı cüzdan","custodial wallet","borsa cüzdanı"],"short":"Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür.","body":[["Merkezi bir borsada hesap açıp kripto yatırdığınızda, varlıklarınız emanetçi bir yapıda tutulur. Anahtarları borsa yönetir; siz kullanıcı adı, şifre ve iki faktörlü doğrulama ile hesabınıza erişirsiniz. Şifrenizi unutursanız hesap kurtarma mümkündür, ",["kurtarma ifadesi","seed-phrase"]," saklamanız gerekmez."],["Kolaylığın karşılığında karşı taraf riski vardır. Borsa saldırıya uğrarsa, iflas ederse veya hesabınızı dondurursa varlıklarınıza erişemeyebilirsiniz. Kripto dünyasında sık tekrarlanan bir söz, anahtarlar sizde değilse coinler de sizin değildir der. Ayrıca para çekme işlemleri borsanın onayına, limitlere ve ",["kimlik doğrulama","kyc"]," kurallarına bağlıdır."],["Riskleri azaltmak için düzenlemeye tabi platformları tercih etmek, ",["rezerv kanıtı (proof of reserves)","proof-of-reserves"]," yayımlayan borsalara bakmak ve uzun süre tutmayı planladığınız büyük tutarları kendi cüzdanınıza çekmek yaygın yöntemlerdir. Türkiye'de ",["kripto varlık","cryptocurrency"]," hizmet sağlayıcıları 2024 düzenlemesiyle SPK lisansına tabi hâle gelmiştir; diğer ülkelerde kurallar farklıdır."]],"example":["Toplam 4.000 ",["USDT","usdt"]," değerinde kriptonuz var. Aktif işlem için 1.000 USDT'yi borsada, yani emanetçi cüzdanda bırakıyor; uzun vadeli tuttuğunuz 3.000 USDT değerindeki ",["BTC","bitcoin"],"'yi kendi donanım cüzdanınıza çekiyorsunuz. Çekim ücreti örneğin 2 USDT ise bu küçük maliyetle varlığınızın yüzde 75'ini borsa riskinden ayırmış olursunuz. Borsada sorun çıkarsa risk altındaki tutar 1.000 USDT ile sınırlı kalır."],"mistakes":["Tüm varlıkları uzun süre tek bir borsada tutmak.","Borsa hesabında iki faktörlü doğrulamayı ve çekim adresi beyaz listesini açmamak.","Emanetçi cüzdandaki bakiyenin her koşulda anında çekilebileceğini varsaymak."],"faq":[{"q":"Emanetçi cüzdan güvenli mi?","a":"Güvenlik, kurumun güvenilirliğine, düzenleyici denetime ve hesabınızın korumasına bağlıdır. Kolaylık sağlar ama kontrolü kuruma bırakırsınız."},{"q":"Emanetçi ve emanetçi olmayan cüzdan farkı nedir?","a":"Emanetçi cüzdanda anahtarları kurum tutar ve hesap kurtarma mümkündür. Emanetçi olmayan cüzdanda anahtarlar ve kurtarma ifadesi sizdedir; kaybederseniz kimse geri getiremez."}],"title":"Emanetçi cüzdan (custodial wallet) nedir?","description":"Emanetçi cüzdanın nasıl çalıştığını, borsada kripto tutmanın risklerini ve bu riskleri nasıl azaltacağınızı öğrenin.","related":[["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur."],["crypto-wallet","Kripto cüzdan (Crypto wallet)","Kripto cüzdan, kripto varlıklarınıza erişmenizi sağlayan özel anahtarları saklayan ve bu anahtarlarla işlem imzalamanıza imkân veren yazılım veya donanımdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"tr","term":"Zincir üstü analiz (on-chain analiz)","aka":["on-chain analiz","zincir üstü veri analizi","on-chain analysis"],"short":"Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir.","body":[["Hisse senetlerinde kimin ne aldığını göremezsiniz. ",["Bitcoin","bitcoin"]," ve ",["Ethereum","ethereum"]," gibi açık ",["blockchain","blockchain"],"'lerde ise her transfer kalıcı olarak kaydedilir. Zincir üstü analiz bu veriyi kullanır: borsalara giren ve çıkan coin miktarı, büyük cüzdanların (balinaların) hareketleri, ",["aktif adres sayısı","active-addresses"],", madenci satışları gibi."],"Teknik analiz fiyat grafiğine, temel analiz projenin değerine bakar. On-chain analiz ise arka plandaki gerçek coin akışını gösterir. Örneğin borsalardan sürekli çıkış, coin'lerin soğuk cüzdanlara çekildiğini düşündürebilir.","Sınırları da vardır. Bir adresin kime ait olduğu her zaman bilinmez, borsaların iç transferleri veriyi yanıltabilir ve aynı veri farklı şekilde yorumlanabilir. Bu yüzden on-chain göstergeler tek başına al-sat sinyali değil, bağlamı tamamlayan bir kaynaktır."],"example":"Bir hafta içinde borsalara 40.000 BTC girdiğini ve 55.000 BTC çıktığını gördüğünüzü varsayalım. Net akış -15.000 BTC olur, yani borsalardaki bakiye azalmıştır. Bu, satışa hazır arzın düştüğü şeklinde yorumlanabilir. Ama aynı hafta bir borsa 10.000 BTC'yi kendi yeni soğuk cüzdanına taşımış olabilir. Analiz aracı bu adresi etiketlememişse gerçek net çıkış yalnızca 5.000 BTC olur. Bu yüzden büyük tek seferlik transferleri ayrıca kontrol etmeniz gerekir.","mistakes":["Tek bir on-chain göstergeye bakıp kesin alım veya satım kararı vermek.","Borsaların iç cüzdan transferlerini gerçek kullanıcı hareketi sanmak.","Etiketsiz bir adresin kesinlikle bir balinaya veya bir kuruma ait olduğunu varsaymak."],"faq":[{"q":"On-chain analiz ne işe yarar?","a":"Coin'lerin borsalara mı yoksa cüzdanlara mı aktığını, ağın ne kadar kullanıldığını ve büyük yatırımcıların ne yaptığını görmenize yardım eder. Fiyat grafiğinin göstermediği arka planı ortaya koyar."},{"q":"On-chain analiz için hangi araçlar kullanılır?","a":"Blok gezginleri ham veriyi gösterir. Glassnode, CryptoQuant ve Nansen gibi analiz platformları bu veriyi grafik ve göstergelere dönüştürür."}],"title":"On-chain analiz nedir? Zincir üstü veriyi okuma","description":"On-chain analiz nedir, borsa akışları ve balina hareketleri nasıl okunur ve bu verinin sınırları nelerdir, örnekle öğrenin.","related":[["exchange-netflow","Borsa giriş ve çıkışları (netflow)","Borsa giriş ve çıkışları, belirli bir sürede borsa cüzdanlarına yatırılan ve oradan çekilen coin miktarını, netflow ise bu ikisi arasındaki farkı gösteren zincir üstü göstergedir."],["whale","Balina (Whale)","Balina, tek başına piyasayı etkileyebilecek kadar büyük miktarda kripto varlık tutan kişi, şirket veya kurumdur."],["active-addresses","Aktif adres sayısı (active addresses)","Aktif adres sayısı, belirli bir sürede, genellikle bir günde, bir blockchain'de işlem gönderen veya alan benzersiz adreslerin sayısıdır ve ağ kullanımını ölçmek için kullanılır."],["block-explorer","Blok gezgini (block explorer)","Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"tr","term":"Grid trading botu (ızgara botu)","aka":["grid bot","grid trading","ızgara botu","ızgara işlem botu"],"short":"Grid trading botu, belirlediğiniz fiyat aralığını eşit basamaklara bölüp her basamakta otomatik alım ve satım emirleri vererek yatay piyasadaki dalgalanmalardan küçük kârlar toplayan bottur.","body":[["Bot için alt fiyat, üst fiyat ve basamak (grid) sayısı belirlersiniz. Bot her basamağa ",["limit emir","limit-order"]," koyar: fiyat düşünce alır, bir üst basamağa çıkınca satar. Her tamamlanan al-sat çifti küçük bir kâr bırakır. Birçok büyük borsa spot ve vadeli grid botlarını hazır araç olarak sunar."],"Grid botu en iyi yatay ve dalgalı piyasada çalışır. Fiyat aralığın üstüne çıkarsa bot tüm coin'leri satmış olur ve yükselişi kaçırırsınız. Aralığın altına düşerse elinizde düşmüş coin'ler kalır ve zarar ortaya çıkar.",["Basamak sayısı arttıkça işlem başına kâr küçülür ve ücretler önem kazanır. Vadeli grid botlarında ",["kaldıraç","leverage"]," eklenince ",["likidasyon","liquidation"]," riski de doğar."]],"example":[["BTC","bitcoin"]," için 56.000 ile 64.000 ",["USDT","usdt"]," arasında 8 basamaklı bir spot grid kurduğunuzu varsayalım. Basamak aralığı 1.000 USDT'dir. Her basamakta 0,01 BTC işlem görür. Fiyat 59.000'e düşüp 60.000'e döndüğünde bot 0,01 BTC'yi 59.000'den alıp 60.000'den satar ve 10 USDT brüt kâr eder. Toplam yüzde 0,1 ücretle yaklaşık 1,19 USDT ödersiniz, net 8,8 USDT kalır. Fiyat ay boyunca bu hareketi 30 kez yaparsa yaklaşık 264 USDT kazanırsınız; fiyat 50.000'e kırılırsa ise alınan coin'lerdeki değer kaybı bu kârı silebilir."],"mistakes":["Güçlü trend olan piyasada dar aralıklı grid kurmak.","Çok sayıda basamak seçip işlem ücretlerinin kârı yemesini hesaba katmamak.","Aralığın dışına çıkıldığında ne yapacağınızı önceden planlamamak."],"faq":[{"q":"Grid bot zarar eder mi?","a":"Evet. Fiyat aralığın altına düşüp orada kalırsa elinizde değeri düşmüş coin'ler kalır ve grid kârından daha büyük bir zarar oluşabilir."},{"q":"Grid bot için en uygun piyasa hangisi?","a":"Belirli bir aralıkta gidip gelen, yatay ve dalgalı piyasa en uygundur. Tek yönlü sert trendlerde grid stratejisi zayıf kalır."}],"title":"Grid bot nedir? Grid trading botu nasıl çalışır","description":"Grid trading botu nedir, fiyat aralığı ve basamak sayısı nasıl seçilir, kâr ve ücret nasıl hesaplanır; örnekle öğrenin.","related":[["dollar-cost-averaging","Düzenli alım stratejisi (DCA)","DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir."],["copy-trading","Kopya işlem (copy trading)","Kopya işlem (copy trading), seçtiğiniz bir trader'ın açtığı ve kapattığı pozisyonların, belirlediğiniz tutar ve oranla sizin hesabınızda otomatik olarak tekrarlanmasıdır."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."]],"lesson":null,"coin":null,"tool":null,"cta":true}});
